	/** Wrap BELOW buffering, so counters and clocks run per file transfer, not per value or row. */
	public InputStream spillInput(InputStream input) {
		return new FilterInputStream(input) {
			@Override
			public int read(byte[] bytes, int offset, int length) throws IOException {
				long started = System.nanoTime();
				try {
					int read = in.read(bytes, offset, length);
					if (read > 0)
						spillReadBytes.add(read);
					return read;
				} catch (IOException failure) {
					spillIoFailures.increment();
					throw failure;
				} finally {
					spillReadNanos.add(System.nanoTime() - started);
				}
			}

			@Override
			public int read() throws IOException {
				long started = System.nanoTime();
				try {
					int read = in.read();
					if (read >= 0)
						spillReadBytes.increment();
					return read;
				} finally {
					spillReadNanos.add(System.nanoTime() - started);
				}
			}
		};
	}

	public OutputStream spillOutput(OutputStream output) {
		return new FilterOutputStream(output) {
			@Override
			public void write(byte[] bytes, int offset, int length) throws IOException {
				long started = System.nanoTime();
				try {
					out.write(bytes, offset, length);
					spillWriteBytes.add(length);
				} catch (IOException failure) {
					spillIoFailures.increment();
					throw failure;
				} finally {
					spillWriteNanos.add(System.nanoTime() - started);
				}
			}

			@Override
			public void write(int value) throws IOException {
				long started = System.nanoTime();
				try {
					out.write(value);
					spillWriteBytes.increment();
				} finally {
					spillWriteNanos.add(System.nanoTime() - started);
				}
			}
		};
	}

	/** Copy only scalar state while the view is pinned. Never retain its native arenas in the explanation. */
